import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const u=JSON.parse('{"title":"UI系统与切换机制解析","description":"","frontmatter":{},"headers":[],"relativePath":"教程资料/专题研究/UI系统与切换机制解析.md","filePath":"教程资料/专题研究/UI系统与切换机制解析.md","lastUpdated":1777893104000}'),h={name:"教程资料/专题研究/UI系统与切换机制解析.md"};function I(U,l,n,d,t,o){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="ui系统与切换机制解析" tabindex="-1">UI系统与切换机制解析 <a class="header-anchor" href="#ui系统与切换机制解析" aria-label="Permalink to “UI系统与切换机制解析”">​</a></h1><p>本文基于官方教程截图中关于 UI 切换、地图 UI、操作 UI、物体 UI 的说明，整理创游世界 UI 系统的结构与常见误区。</p><h2 id="_1-ui-的分类结构" tabindex="-1">1. UI 的分类结构 <a class="header-anchor" href="#_1-ui-的分类结构" aria-label="Permalink to “1. UI 的分类结构”">​</a></h2><p>从教程截图可确认，创游中的 UI 至少分为三类：</p><ul><li>地图 UI</li><li>操作 UI</li><li>物体 UI</li></ul><p>这说明“UI”并不是一个单一对象类型，而是按用途和挂载位置拆分的多个子系统。</p><h3 id="结构理解" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解" aria-label="Permalink to “结构理解”">​</a></h3><ul><li><strong>地图 UI</strong>：更偏全局界面，通常跟地图或场景级逻辑联动。</li><li><strong>操作 UI</strong>：更偏输入、按钮、控制面板等玩家操作层界面。</li><li><strong>物体 UI</strong>：与某个物体绑定，属于组件式 UI 能力。</li></ul><h2 id="_2-为什么切换-ui-时会-找不到做好的-ui" tabindex="-1">2. 为什么切换 UI 时会“找不到做好的 UI” <a class="header-anchor" href="#_2-为什么切换-ui-时会-找不到做好的-ui" aria-label="Permalink to “2. 为什么切换 UI 时会“找不到做好的 UI””">​</a></h2><p>根据截图内容，常见原因不是 UI 消失，而是<strong>指令找错了位置</strong>。</p><p>可提炼出的规则：</p><ul><li>切换不同类型的 UI，要使用对应作用域或对应入口下的指令。</li><li>不能把地图 UI、操作 UI、物体 UI 的切换方式混用。</li><li>尤其是物体 UI，因为它本质上带有“组件属性”，不是纯全局对象，所以调用路径不同。</li></ul><h2 id="_3-物体-ui-的本质-组件化-ui" tabindex="-1">3. 物体 UI 的本质：组件化 UI <a class="header-anchor" href="#_3-物体-ui-的本质-组件化-ui" aria-label="Permalink to “3. 物体 UI 的本质：组件化 UI”">​</a></h2><p>教程截图明确提到：</p><ul><li>物体 UI 是一个组件</li><li>因此需要先给物体挂这个组件，才能使用相应指令</li></ul><p>这意味着：</p><ul><li>物体 UI 不是自动存在的</li><li>也不是所有物体天生可切换物体 UI</li><li>必须先完成“组件挂载 -&gt; 获得能力 -&gt; 再调用切换/显示相关指令”这一链路</li></ul><p>这与创游整体设计高度一致：</p><ul><li>组件决定能力</li><li>脚本决定行为</li><li>UI 也遵循这一能力授权模型</li></ul><h2 id="_4-ui-设计上的分层思想" tabindex="-1">4. UI 设计上的分层思想 <a class="header-anchor" href="#_4-ui-设计上的分层思想" aria-label="Permalink to “4. UI 设计上的分层思想”">​</a></h2><p>结合引擎更新说明，可以把创游 UI 理解为三层：</p><h3 id="_4-1-逻辑触发层" tabindex="-1">4.1 逻辑触发层 <a class="header-anchor" href="#_4-1-逻辑触发层" aria-label="Permalink to “4.1 逻辑触发层”">​</a></h3><p>例如：</p><ul><li>玩家事件</li><li>地图广播</li><li>系统事件</li></ul><h3 id="_4-2-ui-承载层" tabindex="-1">4.2 UI 承载层 <a class="header-anchor" href="#_4-2-ui-承载层" aria-label="Permalink to “4.2 UI 承载层”">​</a></h3><p>也就是：</p><ul><li>当前 UI</li><li>地图 UI</li><li>物体 UI</li><li>操作 UI</li></ul><h3 id="_4-3-ui-内部处理层" tabindex="-1">4.3 UI 内部处理层 <a class="header-anchor" href="#_4-3-ui-内部处理层" aria-label="Permalink to “4.3 UI 内部处理层”">​</a></h3><p>在较新的 UI 逻辑里，官方推荐：</p><ul><li>外部不要直接跨层操作 UI 内细节</li><li>更推荐“向当前 UI 发广播”</li><li>再由 UI 自己处理内部逻辑</li></ul><p>这说明 UI 正在从“被外部强控的显示对象”转向“具备自身脚本自治能力的界面对象”。</p><h2 id="_5-与联机-ui-更新的关系" tabindex="-1">5. 与联机 UI 更新的关系 <a class="header-anchor" href="#_5-与联机-ui-更新的关系" aria-label="Permalink to “5. 与联机 UI 更新的关系”">​</a></h2><p>在引擎更新说明里，<code>玩家.当前UI</code> 被弃用并改为 <code>当前UI</code>，同时推荐：</p><ul><li>执行“玩家.向当前UI发广播”</li><li>让 UI 收到广播后自行处理</li></ul><p>这与教程里的 UI 分类并不冲突，反而形成互证：</p><ul><li>UI 有明确类型与边界</li><li>UI 逻辑更适合在 UI 内部执行</li><li>外部系统负责通知，不负责直接深层操控</li></ul><h2 id="_6-常见误区" tabindex="-1">6. 常见误区 <a class="header-anchor" href="#_6-常见误区" aria-label="Permalink to “6. 常见误区”">​</a></h2><h3 id="误区-1-做好-ui-后所有地方都能直接切换" tabindex="-1">误区 1：做好 UI 后所有地方都能直接切换 <a class="header-anchor" href="#误区-1-做好-ui-后所有地方都能直接切换" aria-label="Permalink to “误区 1：做好 UI 后所有地方都能直接切换”">​</a></h3><p>不对。不同 UI 类型对应的指令位置可能不同。</p><h3 id="误区-2-物体-ui-和地图-ui-没区别" tabindex="-1">误区 2：物体 UI 和地图 UI 没区别 <a class="header-anchor" href="#误区-2-物体-ui-和地图-ui-没区别" aria-label="Permalink to “误区 2：物体 UI 和地图 UI 没区别”">​</a></h3><p>不对。物体 UI 是组件化能力，需要挂载才能使用。</p><h3 id="误区-3-地图脚本应该直接修改-ui-细节" tabindex="-1">误区 3：地图脚本应该直接修改 UI 细节 <a class="header-anchor" href="#误区-3-地图脚本应该直接修改-ui-细节" aria-label="Permalink to “误区 3：地图脚本应该直接修改 UI 细节”">​</a></h3><p>在新逻辑下不推荐。更适合用广播通知 UI 自己更新。</p><h2 id="_7-实战建议" tabindex="-1">7. 实战建议 <a class="header-anchor" href="#_7-实战建议" aria-label="Permalink to “7. 实战建议”">​</a></h2><h3 id="如果你要做全局界面" tabindex="-1">如果你要做全局界面 <a class="header-anchor" href="#如果你要做全局界面" aria-label="Permalink to “如果你要做全局界面”">​</a></h3><p>优先考虑：</p><ul><li>地图 UI</li><li>操作 UI</li></ul><h3 id="如果你要做某个物体头顶血条、提示框、交互标记" tabindex="-1">如果你要做某个物体头顶血条、提示框、交互标记 <a class="header-anchor" href="#如果你要做某个物体头顶血条、提示框、交互标记" aria-label="Permalink to “如果你要做某个物体头顶血条、提示框、交互标记”">​</a></h3><p>优先考虑：</p><ul><li>物体 UI 组件</li></ul><h3 id="如果你在联机模式下写-ui-动画或复杂界面" tabindex="-1">如果你在联机模式下写 UI 动画或复杂界面 <a class="header-anchor" href="#如果你在联机模式下写-ui-动画或复杂界面" aria-label="Permalink to “如果你在联机模式下写 UI 动画或复杂界面”">​</a></h3><p>优先采用：</p><ul><li>外部广播通知</li><li>UI 内脚本处理</li></ul><p>避免：</p><ul><li>频繁在地图脚本里直接操作 UI 公共数据</li><li>让多条同步上传脚本串联</li></ul><h2 id="_8-关键词" tabindex="-1">8. 关键词 <a class="header-anchor" href="#_8-关键词" aria-label="Permalink to “8. 关键词”">​</a></h2><ul><li>UI</li><li>地图UI</li><li>操作UI</li><li>物体UI</li><li>UI切换</li><li>当前UI</li><li>向当前UI发广播</li><li>组件化UI</li><li>联机UI</li></ul><h2 id="_9-来源" tabindex="-1">9. 来源 <a class="header-anchor" href="#_9-来源" aria-label="Permalink to “9. 来源”">​</a></h2><ul><li><code>资料/官方教程文档截图/Screenshot_20260418_120605.jpg</code></li><li><code>资料/创游世界引擎更新说明内容截图/Screenshot_20260418_105516.jpg</code></li><li><code>资料/创游世界引擎更新说明内容截图/Screenshot_20260418_105508.jpg</code></li><li>来源状态：历史来源路径；当前原图目录未列出可直接 OCR 的原图文件，正文依据已归档 OCR 与专题整理。</li></ul>',59)])])}const c=i(h,[["render",I]]);export{u as __pageData,c as default};
